package com.crms.controller;import com.crms.entity.Notification;import com.crms.repository.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/notifications") public class NotificationController{private final NotificationRepository notifications;private final UserRepository users;public NotificationController(NotificationRepository n,UserRepository u){notifications=n;users=u;}@GetMapping("/my")public List<Notification> mine(Authentication a){return notifications.findByUserIdOrderByCreatedAtDesc(users.findByEmailIgnoreCase(a.getName()).orElseThrow().getId());}@PatchMapping("/{id}/read")public Notification read(@PathVariable Long id,Authentication a){var n=notifications.findById(id).orElseThrow();if(!n.getUser().getEmail().equalsIgnoreCase(a.getName()))throw new org.springframework.security.access.AccessDeniedException("Not authorized");n.setReadFlag(true);return notifications.save(n);}}
